True def transform(grid):
    n = len(grid[0])
    center = n // 2
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if r <= center and abs(c - center) == r:
                out[r][c] = 2
            elif r > abs(c - center) and (c - r) % 4 == center % 4:
                out[r][c] = 1
    return out
